import sys

class Rectangle:
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def area(self):
        return self.length * self.width

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    l, w = map(int, data[:2])
    rect = Rectangle(l, w)
    print(rect.area())

if __name__ == "__main__":
    main()
